def make_traces() -> tuple[object, InMemoryTraceQueryClient, list[str]]:
    handle, _, query = init_memory_tracing("api")
    tracer = handle.tracer("t")
    ids = []
    with tracer.start_as_current_span("GET /a") as root:
        with tracer.start_as_current_span("SELECT"):
            pass
        ids.append(format(root.get_span_context().trace_id, "032x"))
    time.sleep(0.002)
    with tracer.start_as_current_span("GET /b") as root:
        ids.append(format(root.get_span_context().trace_id, "032x"))
    handle.force_flush(5)
    return handle, query, ids


def test_memory_queries() -> None:
    handle, query, (first, second) = make_traces()
    assert isinstance(query, TraceQueryClient)
    trace = query.get_trace(first.upper())
    assert trace is not None
    assert len(trace.spans) == 2
    assert query.get_trace("ff" * 16) is None
    summaries = query.search_traces()
    assert [s.trace_id for s in summaries] == [second, first]
    assert [s.trace_id for s in query.search_traces(TraceSearchQuery(operation="SELECT"))] == [
        first
    ]
    assert len(query.search_traces(TraceSearchQuery(limit=1))) == 1
    assert query.list_services() == ["api"]
    assert query.list_operations("api") == ["GET /a", "GET /b", "SELECT"]
    assert query.list_operations("other") == []
    assert query.get_dependencies() == []
    start = micros_to_datetime(trace.spans[0].start_micros)
    assert query.get_dependencies(start=start + timedelta(days=1)) == []
    assert query.get_dependencies(end=start - timedelta(days=1)) == []
    assert query.wait_for_trace(first, timeout_s=1, min_spans=2).trace_id == first
    handle.shutdown()  # type: ignore[attr-defined]


def test_wait_for_trace_polls_and_times_out() -> None:
    handle, _, query = init_memory_tracing("svc")
    tracer = handle.tracer("t")
    span = tracer.start_span("later")
    trace_id = format(span.get_span_context().trace_id, "032x")

    def finish() -> None:
        time.sleep(0.1)
        span.end()
        handle.force_flush(5)

    threading.Thread(target=finish).start()
    trace = wait_for_trace(query, trace_id, timeout_s=5, interval_s=0.02)
    assert trace.spans[0].name == "later"
    with pytest.raises(TimeoutError):
        wait_for_trace(query, trace_id, timeout_s=0.05, interval_s=0.01, min_spans=2)
    handle.shutdown()


def test_wait_for_trace_treats_not_found_as_missing() -> None:
    class NotYet(BaseTraceQueryClient):
        calls = 0

        def get_trace(self, trace_id: str) -> Trace | None:
            self.calls += 1
            if self.calls < 3:
                raise NotFoundError("not indexed yet")
            return Trace(trace_id, [])

    client = NotYet()
    assert client.wait_for_trace("ab", timeout_s=5, interval_s=0.01, min_spans=0).trace_id.endswith(
        "ab"
    )
    assert client.calls == 3


async def test_async_wait_for_trace() -> None:
    class NotYet(AsyncBaseTraceQueryClient):
        calls = 0

        async def get_trace(self, trace_id: str) -> Trace | None:
            self.calls += 1
            if self.calls == 1:
                raise NotFoundError("not yet")
            return None if self.calls == 2 else Trace(trace_id, [])

    client = NotYet()
    trace = await client.wait_for_trace("cd", timeout_s=5, interval_s=0.01, min_spans=0)
    assert trace.trace_id.endswith("cd")
    with pytest.raises(TimeoutError):
        await async_wait_for_trace(NotYet(), "cd", timeout_s=0.05, interval_s=0.01, min_spans=1)


class NativeTrace(Trace):
    normalize_ids = False


def test_wait_for_trace_native_ids() -> None:
    native = "2a1b3c.45.16630000000000001"
    seen: list[str] = []

    class Native(BaseTraceQueryClient):
        def query_trace_id(self, trace_id: str) -> str:
            return trace_id

        def get_trace(self, trace_id: str) -> Trace | None:
            seen.append(trace_id)
            return NativeTrace(trace_id, [])

    assert Native().wait_for_trace(native, timeout_s=1, min_spans=0).trace_id == native
    assert wait_for_trace(Native(), native, timeout_s=1, min_spans=0, normalize=None)
    assert seen == [native, native]
    with pytest.raises(ValidationError):  # the default still normalizes (and rejects) ids
        wait_for_trace(Native(), native, timeout_s=1, min_spans=0)


async def test_async_wait_for_trace_native_ids() -> None:
    native = "segment-7"

    class Native(AsyncBaseTraceQueryClient):
        def query_trace_id(self, trace_id: str) -> str:
            return trace_id

        async def get_trace(self, trace_id: str) -> Trace | None:
            return NativeTrace(trace_id, [])

    assert (await Native().wait_for_trace(native, timeout_s=1, min_spans=0)).trace_id == native
    trace = await async_wait_for_trace(Native(), native, timeout_s=1, min_spans=0, normalize=None)
    assert trace.trace_id == native
    assert AsyncBaseTraceQueryClient().query_trace_id("AB") == "0" * 30 + "ab"


def test_base_client_unsupported() -> None:
    base = BaseTraceQueryClient()
    for call in (
        lambda: base.get_trace("ab"),
        base.search_traces,
        base.list_services,
        lambda: base.list_operations("x"),
        base.get_dependencies,
    ):
        with pytest.raises(UnsupportedError):
            call()


