async def test_async_memory_queries() -> None:
    handle, exporter, _ = init_memory_tracing("web")
    tracer = handle.tracer("t")
    with tracer.start_as_current_span("root") as root:
        pass
    handle.force_flush(5)
    query = AsyncInMemoryTraceQueryClient(exporter)
    assert isinstance(query, AsyncTraceQueryClient)
    trace_id = format(root.get_span_context().trace_id, "032x")
    assert (await query.get_trace(trace_id)) is not None
    assert len(await query.search_traces()) == 1
    assert await query.list_services() == ["web"]
    assert await query.list_operations("web") == ["root"]
    assert await query.get_dependencies() == []
    assert (await query.wait_for_trace(trace_id, timeout_s=1)).trace_id == trace_id
    handle.shutdown()


def test_dependencies_across_services() -> None:
    api, api_exporter, _ = init_memory_tracing("api")
    db, db_exporter, _ = init_memory_tracing("db")
    with api.tracer("t").start_as_current_span("call"), db.tracer("t").start_as_current_span("q"):
        pass
    db.force_flush(5)
    api.force_flush(5)
    # both providers export into their own exporter: merge db spans into the api fake
    combined = InMemoryTraceQueryClient(api_exporter)
    api_exporter._spans.extend(db_exporter.spans)
    assert combined.get_dependencies() == [DependencyLink("api", "db", 1)]
    api.shutdown()
    db.shutdown()
